mapper.select:
SELECT C.CATEGORY_ID AS categoryId, C.CATEGORY_NAME AS categoryName, COUNT(P.PRODUCT_ID) AS productCount FROM PRODUCT_CATEGORIES C, PRODUCTS P WHERE C.CATEGORY_ID = P.CATEGORY_ID(+)
AND C.CATEGORY_ID = #{categoryId}
GROUP BY C.CATEGORY_ID, C.CATEGORY_NAME ORDER BY C.CATEGORY_NAME

mapper.insert:

    SELECT NVL(MAX(CATEGORY_ID), 0) + 1 AS categoryId
      FROM PRODUCT_CATEGORIES

INSERT INTO PRODUCT_CATEGORIES (
    CATEGORY_ID,
    CATEGORY_NAME
) VALUES (
    #{categoryId},
    #{categoryName}
)
